const items = $input.all();

// Agrupar por spreadsheet_id
const porPlanilha = {};
for (const item of items) {
  const sid = item.json.spreadsheet_id;
  const sht = item.json.sheet_title;
  if (!porPlanilha[sid]) {
    porPlanilha[sid] = [];
  }
  porPlanilha[sid].push(sht);
}

// Criar lotes de 5 abas por planilha
const lotes = [];
for (const [spreadsheet_id, sheetTitles] of Object.entries(porPlanilha)) {
  const batchSize = 5;
  for (let i = 0; i < sheetTitles.length; i += batchSize) {
    const batch = sheetTitles.slice(i, i + batchSize);
    const rangesQuery = batch.map(t => 'ranges=' + encodeURIComponent(t)).join('&');

    lotes.push({
      json: {
        spreadsheet_id: spreadsheet_id,
        sheet_titles: batch,
        ranges_query: rangesQuery
      }
    });
  }
}

return lotes;

const todosOsLotes = $input.all();
const resultado = [];

for (const lote of todosOsLotes) {
  const resposta = lote.json;
  const spreadsheet_id = resposta.spreadsheetId;
  const valueRanges = resposta.valueRanges || [];

  for (const vr of valueRanges) {
    const sheetName = vr.range.split('!')[0];
    resultado.push({
      json: {
        spreadsheet_id: spreadsheet_id,
        sheet_title: sheetName,
        values: vr.values || []
      }
    });
  }
}

return resultado;

const items = $input.all();

// Separa feriados dos dados da planilha
const feriados = items.filter(i => i.json.date && i.json.name);
const linhas = items.filter(i => i.json['Vencimento']);

const feriadosSet = new Set(feriados.map(f => f.json.date));

function isWeekendOrHoliday(date) {
  const day = date.getDay();
  const yyyy = date.getFullYear();
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  const dd = String(date.getDate()).padStart(2, '0');
  const iso = `${yyyy}-${mm}-${dd}`;
  return day === 0 || day === 6 || feriadosSet.has(iso);
}

function parseBR(dateStr) {
  const [d, m, y] = String(dateStr).split('/');
  return new Date(Number(y), Number(m) - 1, Number(d));
}

function formatBR(date) {
  const dd = String(date.getDate()).padStart(2, '0');
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  const yyyy = date.getFullYear();
  return `${dd}/${mm}/${yyyy}`;
}

const paraAjustar = [];
const paraEnviar = [];

for (const item of linhas) {
  const vencimento = item.json['Vencimento'];
  if (!vencimento) continue;

  const date = parseBR(vencimento);

  if (isWeekendOrHoliday(date)) {
    let novaData = new Date(date);
    do {
      novaData.setDate(novaData.getDate() + 1);
    } while (isWeekendOrHoliday(novaData));

    paraAjustar.push({
      json: {
        ...item.json,
        Vencimento: formatBR(novaData),
        _precisa_ajustar: true
      }
    });
  } else {
    paraEnviar.push({
      json: {
        ...item.json,
        _precisa_ajustar: false
      }
    });
  }
}

return [...paraAjustar, ...paraEnviar];

// Recebe N itens (um por planilha), cada um com spreadsheetId e sheets[]
// Expande para um item por aba
const resultado = [];
for (const item of $input.all()) {
  const spreadsheetId = item.json.spreadsheetId;
  const sheets = item.json.sheets || [];
  for (const sheet of sheets) {
    resultado.push({
      json: {
        spreadsheet_id: spreadsheetId,
        sheet_title: sheet.properties.title
      }
    });
  }
}
return resultado;

const resultado = [];
const todosItens = $input.all();

for (let idx = 0; idx < todosItens.length; idx++) {
  const item = todosItens[idx];
  const rows = item.json.values || [];

  // Pega spreadsheet_id e sheet_title do Expande abas pelo mesmo índice
  const aba = $('Expande abas').all()[idx];
  const spreadsheetId = aba ? aba.json.spreadsheet_id : '';
  const sheetTitle = aba ? aba.json.sheet_title : '';

  // Busca dinamicamente a linha de headers
  let headerIndex = -1;
  for (let i = 0; i < rows.length; i++) {
    if (rows[i].some(c => String(c).trim() === 'Vencimento' || String(c).trim() === 'Parcelas')) {
      headerIndex = i;
      break;
    }
  }
  if (headerIndex === -1) continue;

  const headers = rows[headerIndex];
  const dataRows = rows.slice(headerIndex + 1);

  for (let rowIdx = 0; rowIdx < dataRows.length; rowIdx++) {
    const row = dataRows[rowIdx];
    const primeira = String(row[0] ?? '').trim().toUpperCase();
    if (primeira === 'TOTAL' || primeira === '') continue;

    const obj = {};
    headers.forEach((h, i) => {
      obj[String(h).trim()] = row[i] ?? '';
    });

    resultado.push({
      json: {
        ...obj,
        spreadsheet_id: spreadsheetId,
        sheet_title: sheetTitle,
        row_number: headerIndex + rowIdx + 2
      }
    });
  }
}
return resultado;

// Nó: Filtra vencimento hoje e verifica inadimplência
// Recebe todas as linhas mapeadas e:
// 1. Filtra apenas os clientes com vencimento HOJE e sem data de recebimento
// 2. Para cada um, verifica se o mesmo contato tem parcelas ANTERIORES vencidas e não pagas
// 3. Anexa a lista de inadimplências ao item

const todasLinhas = $input.all();

const hoje = $now.setZone('America/Sao_Paulo').toFormat('dd/MM/yyyy');

function parseBR(dateStr) {
  const parts = String(dateStr).split('/');
  if (parts.length !== 3) return null;
  return new Date(Number(parts[2]), Number(parts[1]) - 1, Number(parts[0]));
}

const dataHoje = parseBR(hoje);

// Filtra linhas com vencimento hoje e sem recebimento
const vencemHoje = todasLinhas.filter(i => {
  return (
    String(i.json['Vencimento']).trim() === hoje &&
    String(i.json['Data recebimento'] ?? '').trim() === ''
  );
});

if (vencemHoje.length === 0) return [];

// Para cada linha que vence hoje, busca inadimplências do mesmo contato
const resultado = [];

for (const itemHoje of vencemHoje) {
  const contato = String(itemHoje.json['Contato:'] ?? '').trim();
  const spreadsheetId = itemHoje.json.spreadsheet_id;
  const sheetTitle = itemHoje.json.sheet_title;

  // Busca parcelas anteriores vencidas e não pagas do mesmo contato e mesma aba
  const inadimplentes = todasLinhas.filter(i => {
    const mesmaPlanilha = i.json.spreadsheet_id === spreadsheetId && i.json.sheet_title === sheetTitle;
    const mesmoContato = String(i.json['Contato:'] ?? '').trim() === contato;
    const semRecebimento = String(i.json['Data recebimento'] ?? '').trim() === '';
    const venc = i.json['Vencimento'];
    if (!venc || !mesmaPlanilha || !mesmoContato || !semRecebimento) return false;
    const dataVenc = parseBR(venc);
    if (!dataVenc) return false;
    // Apenas parcelas com vencimento ANTERIOR a hoje (não inclui a de hoje)
    return dataVenc < dataHoje;
  });

  // Monta lista de inadimplências como array simples para uso no próximo nó
  const listaInadimplentes = inadimplentes.map(i => ({
    parcela: i.json['Parcelas'],
    valor: i.json['Valor'],
    vencimento: i.json['Vencimento']
  }));

  resultado.push({
    json: {
      ...itemHoje.json,
      _inadimplentes: listaInadimplentes
    }
  });
}

return resultado;

// Processa TODOS os items de entrada
const resultado = [];

for (const item of $input.all()) {
  const nome = item.json['Nome:'] ?? '';
  const parcela = item.json['Parcelas'] ?? '';
  const valor = item.json['Valor'] ?? '';
  const vencimento = item.json['Vencimento'] ?? '';
  const contato = '55' + String(item.json['Contato:'] ?? '').trim();
  const inadimplentes = item.json['_inadimplentes'] || [];

  let mensagem = `Bom dia, ${nome}. Informamos que a ${parcela}ª parcela do seu acordo, no valor de ${valor}, vence hoje, ${vencimento}.\n\nO cumprimento do prazo é essencial para a manutenção dos termos acordados entre as partes.`;

  if (inadimplentes.length > 0) {
    mensagem += `\n\nAlém disso, identificamos parcelas anteriores em aberto:`;
    for (const p of inadimplentes) {
      mensagem += `\n- Parcela Nº${p.parcela} — ${p.valor} — vencida em ${p.vencimento}`;
    }
    mensagem += `\n\nPor favor, entre em contato para regularizarmos a situação.`;
  }

  mensagem += `\n\nAtenciosamente,\nViana Advocacia.`;

  resultado.push({
    json: {
      numero: contato,
      mensagem: mensagem
    }
  });
}

return resultado;
